fn decode_reverse(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xfb00070 != 0x6b00030 {
        return Err(DecodeError::Unallocated);
    }
    // cond=xxxx|011|01|o1=x|11xxxx|Rd=xxxx|xxxx|o2=x|01|1|Rm=xxxx
    let Rd: u8 = ((bits >> 12) & 0xf) as u8;
    let Rm: u8 = (bits & 0xf) as u8;
    let unpredictable: bool = bits & 0xf0f00 != 0xf0f00 || Rd == 15 || Rm == 15;
    let cond: u8 = (bits >> 28) as u8;
    match bits & 0x400080 {
        0 => {
            // REV
            // REV{<c>}{<q>}  <Rd>, <Rm>
            Ok(Instruction::RevA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                Rm: GpReg::new(Rm),
                unpredictable,
            })
        }
        128 => {
            // REV16
            // REV16{<c>}{<q>}  <Rd>, <Rm>
            Ok(Instruction::Rev16A1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                Rm: GpReg::new(Rm),
                unpredictable,
            })
        }
        0x400000 => {
            // RBIT
            // RBIT{<c>}{<q>}  <Rd>, <Rm>
            Ok(Instruction::RbitA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                Rm: GpReg::new(Rm),
                unpredictable,
            })
        }
        0x400080 => {
            // REVSH
            // REVSH{<c>}{<q>}  <Rd>, <Rm>
            Ok(Instruction::RevshA1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                Rm: GpReg::new(Rm),
                unpredictable,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

fn decode_sat16(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xfb000f0 != 0x6a00030 {
        return Err(DecodeError::Unallocated);
    }
    // cond=xxxx|011|01|U=x|10|sat_imm=xxxx|Rd=xxxx|xxxx|001|1|Rn=xxxx
    let Rd: u8 = ((bits >> 12) & 0xf) as u8;
    let Rn: u8 = (bits & 0xf) as u8;
    let sat_imm: u8 = ((bits >> 16) & 0xf) as u8;
    let unpredictable: bool = bits & 0xf00 != 0xf00 || Rd == 15 || Rn == 15;
    let cond: u8 = (bits >> 28) as u8;
    match bits & 0x400000 {
        0 => {
            // SSAT16
            // SSAT16{<c>}{<q>}  <Rd>, #<imm>, <Rn>
            let saturate_to: i64 = sat_imm as i64 + 1;
            Ok(Instruction::Ssat16A1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                imm: saturate_to,
                Rn: GpReg::new(Rn),
                unpredictable,
            })
        }
        0x400000 => {
            // USAT16
            // USAT16{<c>}{<q>}  <Rd>, #<imm>, <Rn>
            Ok(Instruction::Usat16A1 {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                imm: sat_imm,
                Rn: GpReg::new(Rn),
                unpredictable,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

fn decode_sat32(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xfa00030 != 0x6a00010 {
        return Err(DecodeError::Unallocated);
    }
    // cond=xxxx|01101|U=x|1|sat_imm=xxxxx|Rd=xxxx|imm5=xxxxx|sh=x|01|Rn=xxxx
    let Rd: u8 = ((bits >> 12) & 0xf) as u8;
    let Rn: u8 = (bits & 0xf) as u8;
    let sat_imm: u8 = ((bits >> 16) & 0x1f) as u8;
    let imm5: u8 = ((bits >> 7) & 0x1f) as u8;
    let unpredictable: bool = Rd == 15 || Rn == 15;
    let cond: u8 = (bits >> 28) as u8;
    match bits & 0x400040 {
        0 => {
            // SSAT — Logical shift left
            // SSAT{<c>}{<q>}  <Rd>, #<imm>, <Rn> {, LSL #<amount>}
            let saturate_to: i64 = sat_imm as i64 + 1;
            Ok(Instruction::SsatA1Lsl {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                imm: saturate_to,
                Rn: GpReg::new(Rn),
                amount: imm5,
                unpredictable,
            })
        }
        64 => {
            // SSAT — Arithmetic shift right
            // SSAT{<c>}{<q>}  <Rd>, #<imm>, <Rn>, ASR #<amount>
            let saturate_to: i64 = sat_imm as i64 + 1;
            let (shift_t, shift_n) = shared::DecodeImmShift(0b10, imm5);
            let shift_n: i64 = shift_n as i64;
            Ok(Instruction::SsatA1Asr {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                imm: saturate_to,
                Rn: GpReg::new(Rn),
                amount: shift_n,
                unpredictable,
            })
        }
        0x400000 => {
            // USAT — Logical shift left
            // USAT{<c>}{<q>}  <Rd>, #<imm>, <Rn> {, LSL #<amount>}
            Ok(Instruction::UsatA1Lsl {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                imm: sat_imm,
                Rn: GpReg::new(Rn),
                amount: imm5,
                unpredictable,
            })
        }
        0x400040 => {
            // USAT — Arithmetic shift right
            // USAT{<c>}{<q>}  <Rd>, #<imm>, <Rn>, ASR #<amount>
            let (shift_t, shift_n) = shared::DecodeImmShift(0b10, imm5);
            let shift_n: i64 = shift_n as i64;
            Ok(Instruction::UsatA1Asr {
                cond: match Cond::from_bits(cond) {
                    Some(cond) => cond,
                    None => return Err(DecodeError::Unallocated),
                },
                Rd: GpReg::new(Rd),
                imm: sat_imm,
                Rn: GpReg::new(Rn),
                amount: shift_n,
                unpredictable,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

